package com.astra.alive;
import android.app.Activity;import android.os.Bundle;import android.view.View;import android.view.Window;import android.view.WindowManager;import android.webkit.WebSettings;import android.webkit.WebView;import android.webkit.WebViewClient;
public class MainActivity extends Activity { private WebView game; @Override protected void onCreate(Bundle b){super.onCreate(b);getWindow().requestFeature(Window.FEATURE_NO_TITLE);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);immersive();game=new WebView(this);game.setBackgroundColor(0xFF101910);game.setOverScrollMode(View.OVER_SCROLL_NEVER);WebSettings s=game.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(true);s.setSupportZoom(false);game.setWebViewClient(new WebViewClient());setContentView(game);game.loadUrl("file:///android_asset/index.html");} private void immersive(){getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY|View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN|View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_LAYOUT_STABLE);} @Override public void onWindowFocusChanged(boolean f){super.onWindowFocusChanged(f);if(f)immersive();} @Override protected void onDestroy(){if(game!=null){game.destroy();game=null;}super.onDestroy();}}
